import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var values = React.useState(['Топливо', 'Пробег']), message = React.useState('');
    function remove(value) { values[1](values[0].filter(function (v) { return v !== value; })); message[1]('Удалено значение «' + value + '».'); document.getElementById('restore-values').focus(); }
    return <div className="dschip-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'row'}>
    {values[0].map(function (value) {
            return <S.DsChip key={value} removable={true} onRemove={function () { remove(value); }}>
    {value}
    </S.DsChip>;
        })}
    </div>
    <div>
    <S.DsButton id={'restore-values'} size={'sm'} tone={'secondary'} onClick={function () { values[1](['Топливо', 'Пробег']); message[1]('Значения восстановлены.'); }}>
    {'Восстановить значения'}
    </S.DsButton>
    </div>
    <p className={'cap'} role={'status'}>
    {message[0] || 'Удалите значение крестиком.'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dschip-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dschip-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dschip-example p{margin:0}\n.dschip-example .row{display:flex;flex-wrap:wrap;gap:12px;align-items:center}\n.dschip-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}";

export { App as Example };

