import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var longValue = React.useState(true), longMessage = React.useState('');
    return <div className="dschip-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'row'}>
    {longValue[0] ? <S.DsChip removable={true} maxWidth={220} onRemove={function () { longValue[1](false); longMessage[1]('Длинное значение удалено.'); document.getElementById('restore-long-value').focus(); }}>
    {'Объекты северо-западного подразделения'}
    </S.DsChip> : null}
    <S.DsChip removable={true} disabled={true}>
    {'Обязательная группа'}
    </S.DsChip>
    </div>
    <p className={'cap'}>
    {'Обязательная группа закреплена администратором.'}
    </p>
    <div><S.DsButton id="restore-long-value" size="sm" tone="secondary" onClick={() => { longValue[1](true); longMessage[1]('Длинное значение восстановлено.'); }}>Восстановить длинное значение</S.DsButton></div>
    <p className="cap" role="status">{longMessage[0] || 'Удалите длинное значение крестиком.'}</p>
    </div>
    </div>;
}

const exampleStyles = ".dschip-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dschip-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dschip-example p{margin:0}\n.dschip-example .row{display:flex;flex-wrap:wrap;gap:12px;align-items:center}\n.dschip-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}";

export { App as Example };
